const SIZE=30;let grid=Array.from({length:SIZE},(_,y)=>Array.from({length:SIZE},(_,x)=>{
 if(x<1||y<1||x>=SIZE-1||y>=SIZE-1)return 1;
 if(x%6!==0&&y%6!==0)return 1+((x*7+y*13)%4===0?1:0);
 return 0;
}));
function openCell(x,y){if(x>=0&&y>=0&&x<SIZE&&y<SIZE)grid[y][x]=0}
// Roads, plazas, accessible doorways and open public spaces.
locations.forEach(l=>{for(let y=l.y-1;y<=l.y+1;y++)for(let x=l.x-1;x<=l.x+1;x++)if(x%6===0||y%6===0||Math.abs(x-l.x)<=1&&Math.abs(y-l.y)<=1)openCell(x,y)});
items.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));evidence.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));
persons.forEach(o=>openCell(Math.round(o.x),Math.round(o.y)));
// Iconic landmarks: heavy facades beside their public approach.
