content.text:
.modal{position:absolute;z-index:12;inset:0;background:rgba(3,6,6,.72);display:grid;place-items:center}
.modal-card{position:relative;width:min(470px,90vw);padding:34px;background:#141b18;border:1px solid rgba(219,202,162,.25);box-shadow:0 20px 90px #000}
.modal-close{position:absolute;right:17px;top:15px}
.key-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin:22px 0}
.muted{color:#92958b!important;font-size:11px!important}
.modal-ok{margin-top:7px}
.ending{background:rgba(7,10,9,.94)}
.title-wrap{margin:0}
.mobile-controls{display:none}
.topbar{height:60px;padding:0 17px}
.top-center{gap:7px;font-size:8px}
.brand-name{font-size:10px;letter-spacing:1.5px}
.brand-sub{font-size:7px}
.brand-mark{font-size:23px}
.hud-left{left:5%;top:20%;width:250px}
.hud-right{right:4%;top:22%;width:145px}
.bottom-hud{height:75px;padding:0 12px}
.control-hint{display:none}
.radio{width:auto;padding-left:9px;border:0}
.nav-button{padding:11px 7px;font-size:8px}
.panel{top:60px;bottom:75px}
.title-wrap{margin-left:-10%}
.top-center{position:absolute;top:61px;left:18px;background:rgba(7,10,9,.48);padding:6px 9px}
.topbar{height:56px}
.hud-left{top:17%;width:215px}
.hud-right{top:auto;bottom:103px;right:12px;width:124px;padding:8px 0}
.stat{margin-bottom:8px}
.weather-note{font-size:8px;margin-top:6px}
.bottom-hud{height:68px;padding:0 4px}
.nav-button{padding:10px 6px;font-size:7px;letter-spacing:.3px}
.radio{display:none}
.panel{top:56px;bottom:68px;width:100%}
.panel-head{padding:20px 20px 14px}
.panel-content{padding:16px 20px}
.title-wrap{margin-left:0;width:88vw}
.subtitle{letter-spacing:2.4px}
.start-foot{font-size:7px}
.dialogue{padding-bottom:80px}
.dialogue-card{padding:17px}
.interaction-prompt{top:57%}

